Implement a debounce circuit for a noisy input signal. This module uses a clock signal to ensure that the output only changes states after the input signal has remained stable for a specified duration, defined by the counter_value. The counter increments while the input signal remains unchanged and resets if a change is detected, effectively filtering out rapid fluctuations in the input signal. When the counter reaches its maximum value, the stable input state is registered as the output.
module top_module(
		clk,
		in,
		out
	);

code:
module top_module(
		clk,
		in,
		out
	);parameter counter_width = 20;
parameter counter_value = 1000000;

input			clk;
input			in;
output reg	out = 0;

reg prev_in = 0;
reg[counter_width-1 : 0] counter = 0;

always @(posedge clk) begin
	if(counter == counter_value)
		out <= prev_in;

	if(in != prev_in)
		counter <= 0;
	else
		counter <= counter + 1;

	prev_in <= in;
end

endmodule

