code:
module top_module(
    input [7:0] A,
    input [7:0] B,
    input [1:0] op,
    input clk,
    input rst,
    output reg [7:0] out,
    output reg valid
);reg [15:0] mul; // used for multiplication
reg [7:0] div; // used for division
reg [1:0] state; // state machine state

always @(posedge clk, posedge rst) begin
    if (rst) begin
        out <= 0;
        valid <= 0;
        state <= 0;
    end else begin
        case (state)
            0: begin // idle
                out <= 0;
                valid <= 0;
                if (op != 2'b00) // if op is not addition, go to next state
                    state <= 1;
            end
            1: begin // addition or subtraction
                if (op == 2'b00) begin // addition
                    out <= A + B;
                end else begin // subtraction
                    out <= A - B;
                end
                valid <= 1;
                state <= 0;
            end
            2: begin // multiplication
                mul <= A * B;
                state <= 3;
            end
            3: begin // multiplication result
                out <= mul[15:8];
                valid <= 1;
                state <= 4;
            end
            4: begin // multiplication result
                out <= mul[7:0];
                valid <= 1;
                state <= 0;
            end
            5: begin // division
                if (B == 0) begin // divide by zero error
                    out <= 0;
                    valid <= 0;
                    state <= 0;
                end else begin
                    div <= A / B;
                    state <= 6;
                end
            end
            6: begin // division result
                out <= div;
                valid <= 1;
                state <= 0;
            end
        endcase
    end
end

endmodule

description:
Design a 4-bit binary adder that computes the sum of two 4-bit inputs A and B. The module calculates each bit of the sum sequentially, propagating a carry signal as necessary to account for addition overflow. The final output is a 4-bit result representing the sum of the inputs.
module top_module(
    input [3:0] A,
    input [3:0] B,
    output reg [3:0] Sum
);

code:
module top_module(
    input [3:0] A,
    input [3:0] B,
    output reg [3:0] Sum
);reg carry;

always @ (A or B)
begin
    Sum[0] = A[0] ^ B[0];
    carry = A[0] & B[0];

    Sum[1] = A[1] ^ B[1] ^ carry;
    carry = (A[1] & B[1]) | (A[1] & carry) | (B[1] & carry);

    Sum[2] = A[2] ^ B[2] ^ carry;
    carry = (A[2] & B[2]) | (A[2] & carry) | (B[2] & carry);

    Sum[3] = A[3] ^ B[3] ^ carry;
end

endmodule

