module top_module(LogicImm, LowLogicImm, HighLogicImm,LowMaskSel_Top, HighMaskSel_Top, LowMaskSel_Bot, HighMaskSel_Bot);input [4:0] LowMaskSel_Top, HighMaskSel_Top; 
  input [4:0] LowMaskSel_Bot, HighMaskSel_Bot; 
