  input wire [31:0] counter_val,
  input wire [1:0] counter_ch,
  output reg counter0_OUT,
  output reg counter1_OUT,
  output reg counter2_OUT,
  output reg [31:0] counter_out
);reg [31:0] counter0, counter1, counter2;
  reg [1:0] counter_sel;

  always @ (posedge clk or posedge rst) begin
    if (rst) begin
      counter0 <= 0;
      counter1 <= 0;
      counter2 <= 0;
      counter_sel <= 0;
    end else begin
      if (counter_sel == 0) begin
        counter0 <= counter0 + 1;
      end else if (counter_sel == 1) begin
        counter1 <= counter1 + 1;
      end else begin
        counter2 <= counter2 + 1;
      end
    end
  end

  always @ (posedge clk0 or posedge clk1 or posedge clk2) begin
    if (counter_ch == 0) begin
      counter_sel <= 0;
    end else if (counter_ch == 1) begin
      counter_sel <= 1;
    end else begin
      counter_sel <= 2;
    end
  end

  always @ (posedge clk or posedge rst) begin
    if (rst) begin
      counter0_OUT <= 0;
      counter1_OUT <= 0;
      counter2_OUT <= 0;
      counter_out <= 0;
    end else begin
      counter0_OUT <= counter0;
      counter1_OUT <= counter1;
      counter2_OUT <= counter2;
      if (counter_sel == 0) begin
        counter_out <= counter0;
      end else if (counter_sel == 1) begin
        counter_out <= counter1;
      end else begin
        counter_out <= counter2;
      end
    end
  end

  always @ (posedge clk or posedge rst) begin
    if (rst) begin
      counter0 <= 0;
      counter1 <= 0;
      counter2 <= 0;
    end else begin
      if (counter_we) begin
        if (counter_sel == 0) begin
          counter0 <= counter_val;
        end else if (counter_sel == 1) begin
          counter1 <= counter_val;
        end else begin
          counter2 <= counter_val;
        end
      end
    end
  end

endmodule

module down_counter (
    input               clk,
    input               rst,
    output reg [3:0]    count
);

    always @(posedge clk) begin
        if (rst) begin
            count <= 4'b1111;
        end else begin
            count <= count - 1;
        end
    end

endmodule

