module top_module(clk_in1, clk_out1, resetn, locked);input clk_in1;
  output clk_out1;
  input resetn;
  output locked;

  reg locked_reg, clk_out_reg;
  reg [22:0] counter_reg;
  parameter COUNT_MAX = 500000;

  always @(posedge clk_in1 or negedge resetn) begin
    if (~resetn) begin
      locked_reg <= 1'b1;
      clk_out_reg <= 1'b0;
      counter_reg <= 0;
    end
    else begin
      if (counter_reg == COUNT_MAX) begin
        counter_reg <= 0;
        clk_out_reg <= ~clk_out_reg;
      end
      else begin
        counter_reg <= counter_reg + 1;
      end

      if (clk_out_reg == 1'b1) begin
        locked_reg <= 1'b0;
      end
      else begin
        locked_reg <= 1'b1;
      end
    end
  end

  assign locked = locked_reg;
  assign clk_out1 = clk_out_reg;

endmodule

