module top_module(
    input clk,
    input d,
    output q,
    input [7:0] in,
    output [7:0] out,
    input select
);// Dual-edge triggered flip-flop module
    reg d_ff;
    always @(posedge clk, negedge clk) begin
        if (select == 0) begin
            d_ff <= d;
        end
    end
    assign q = d_ff;

    // Barrel shifter module
    wire [7:0] shifted_in;
    assign shifted_in = (select == 1) ? in : q;
    assign out = {shifted_in[7], shifted_in[6], shifted_in[5], shifted_in[4], shifted_in[3], shifted_in[2], shifted_in[1], shifted_in[0]};

endmodule

