module binary_counter (
	input clk,
	input reset_n,
	output [1:0] count);reg [1:0] count_reg = 2'b00;

	always @(posedge clk or negedge reset_n) begin
		if (!reset_n)
			count_reg <= 2'b00;
		else
			count_reg <= count_reg + 1;
	end

	assign count = count_reg;

endmodule

