module debouncer(
	input clk,
	input rst_n,
	input button_in,
	output reg button_out
);

	reg [15:0] shift_reg;

	always @(posedge clk or negedge rst_n) begin
		if (!rst_n)
			shift_reg <= 16'b0;
		else
			shift_reg <= {shift_reg[14:0], button_in};
	end

	always @(posedge clk or negedge rst_n) begin
		if (!rst_n)
			button_out <= 1'b0;
		else if (&shift_reg[15:0] || ~|shift_reg[15:0])
			button_out <= shift_reg[15];
	end

endmodule

