module fsm (
  input clk,
  input reset,
  input e,
  output reg m);parameter S0=0, S1=1, S2=2, S3=3;
	reg [1:0] state, next;

	always @(posedge clk) begin
		if (reset) state <= S0;
		else state <= next;
	end

	always_comb begin
		case (state)
			S0: next = e ? S2 : S1;
			S1: next = e ? S0 : S3;
			S2: next = e ? S3 : S0;
			S3: next = e ? S1 : S2;
			default: next = 'x;
		endcase
	end

	assign m = (state == S1) || (state == S3);

endmodule

