module top_module(
  input clk,
  input reset,
  output reg [1:0] light_status
);reg [1:0] state;
  reg [3:0] count;

  parameter RED = 2'b01;
  parameter GREEN = 2'b10;
  parameter YELLOW = 2'b11;

  always @(posedge clk) begin
    if (reset) begin
      state <= RED;
      count <= 0;
    end else begin
      case (state)
        RED: begin
          if (count == 10) begin
            state <= GREEN;
            count <= 0;
          end else begin
            count <= count + 1;
          end
        end
        GREEN: begin
          if (count == 10) begin
            state <= YELLOW;
            count <= 0;
          end else begin
            count <= count + 1;
          end
        end
        YELLOW: begin
          if (count == 10) begin
            state <= RED;
            count <= 0;
          end else begin
            count <= count + 1;
          end
        end
      endcase
    end
  end

  always @(state) begin
    case (state)
      RED: light_status <= {1'b1, 1'b0};
      GREEN: light_status <= {1'b0, 1'b1};
      YELLOW: light_status <= {1'b0, 1'b0};
    endcase
  end

endmodule

module top_module(out,in1,in2);input [31:0] in1,in2;
	output reg [31:0] out;
	reg [7:0] prod_exp; 
	reg [22:0] prod_man;
	reg prod_sign;
	reg [47:0] temp;
	always @ (*)
	begin
		prod_exp = in1[30:23]+in2[30:23]-127;
		prod_sign = in1[31] ^ in2[31];
		temp = {1'b1,in1[22:0]} * {1'b1,in2[22:0]};
		if (temp[47]) begin
			prod_man = temp[46:24] + temp[23];
			prod_exp = prod_exp + 8'b1;
		end
		else
			prod_man = temp[45:23] + temp[22];
		out = {prod_sign,prod_exp,prod_man};
	end
endmodule

