module fsm (
        input clk,
        input reset,
        input a,
        output reg y);parameter Q0=0, Q1=1, Q2=2, Q3=3;
	reg [1:0] state, next;

	always @(posedge clk)
		if (reset)
			state <= Q0;
		else 
			state <= next;


	always_comb begin
		case(state)
			Q0: next = a ? Q2 : Q1;
			Q1: next = a ? Q0 : Q3;
			Q2: next = a ? Q3 : Q1;
			Q3: next = a ? Q0 : Q2;
			default: next = 'x;
		endcase
	end

	assign y = (state == Q1 || state == Q3);

endmodule

