module top_module(input x, input y, output z);wire q4b_z, q4a_z;

    assign q4b_z = (~x & ~y) | (x & y);
    assign q4a_z = (x ^ y) & x;

    assign z = (q4a_z | q4b_z) ^ (q4a_z & q4b_z);

endmodule

