module top_module(
    data,
    wren,
    wraddress,
    rdaddress,
    wrclock,
    rdclock,
    q
);input [31:0] data;
input wren;
input [4:0] wraddress;
input [3:0] rdaddress;
input wrclock;
input rdclock;
output reg [63:0] q;

reg [31:0] mem32 [0:31];
reg [63:0] mem64 [0:15];

// Write logic for mem32
always @(posedge wrclock) begin
    if (wren) begin
        mem32[wraddress] <= data;
        // Update mem64 as well when data is written to mem32
        mem64[wraddress[4:2]] <= {mem32[wraddress], 32'b0}; // Store 32-bit data into the corresponding 64-bit memory location
    end
end

// Read logic for mem64
always @(posedge rdclock) begin
    q <= mem64[rdaddress];
end

endmodule

module top_module(
    clk_i,
	 rst_n,
	 hour1,
	 hour0,
	 day_en
	 );input clk_i;
input rst_n;
output [3:0] hour1;
output [3:0] hour0;
output day_en;

reg [3:0] hour1;
reg [3:0] hour0;
reg day_en;

reg [3:0] hour1_tmp;
reg [3:0] hour0_tmp;
reg day_en_tmp;



always@(hour1 or hour0)
begin
	if(hour1==4'd2 && hour0==4'd3)
	begin
		hour1_tmp=4'd0;
		hour0_tmp=4'd0;
		day_en_tmp=1'b1;
	end
	else if(hour0==4'd9)
	begin
		hour1_tmp=hour1+4'd1;
		hour0_tmp=4'd0;
		day_en_tmp=1'b0;
	end
	else
	begin
		hour1_tmp=hour1;
		hour0_tmp=hour0+4'd1;
		day_en_tmp=1'b0;
	end
end



always@(posedge clk_i or negedge rst_n)
begin
	if(~rst_n)
	begin
		hour1<=4'd0;
		hour0<=4'd0;
		day_en<=1'b0;
	end
	else
	begin
		hour1<=hour1_tmp;
		hour0<=hour0_tmp;
		day_en<=day_en_tmp;
	end
end



endmodule

