always @(posedge clk)
begin
    if(start) begin
        score <= score + n_lines * n_lines * level;
        lines <= lines + n_lines;
    end
    if(lines >= 6) begin
        lines <= 0;
        level <= level + 8'd1;
    end
    if(rst) begin
        level <= 1;
        lines <= 0;
        score <= 0;
    end
end

