description:
Design a digital potentiometer that adjusts its output resistance based on control signals and an increment/decrement signal. The module takes an n-bit control input to select a starting resistance value between a defined minimum (Rmin) and maximum (Rmax) in discrete steps (Rstep). The output wiper indicates the current resistance setting, which increments or decrements based on the inc signal. The output is constrained to remain within valid ranges, thus ensuring it does not exceed the maximum or fall below zero.
module top_module(
  input [n-1:0] ctrl,
  input inc,
  output reg [log2(Rmax-Rmin+1)-1:0] wiper
);

code:
module top_module(
  input [n-1:0] ctrl,
  input inc,
  output reg [log2(Rmax-Rmin+1)-1:0] wiper
);parameter n = 8; // number of control signals
parameter Rmin = 0; // minimum resistance value
parameter Rmax = 1000; // maximum resistance value
parameter Rstep = 10; // step size for increment/decrement

// Function to calculate log2 of a number
function integer log2;
  input integer value;
  begin
    log2 = 0;
    while (2**log2 < value) begin
      log2 = log2 + 1;
    end
  end
endfunction

reg [log2(Rmax-Rmin+1)-1:0] resistance;

// Initialize wiper to 0 at the start
initial begin
  wiper = 0;
end

always @(*) begin
  resistance = (ctrl * Rstep) + Rmin;
  if (inc) begin
    wiper <= wiper + 1;
  end else begin
    wiper <= wiper - 1;
  end
  if (wiper < 0) begin
    wiper <= 0;
  end else if (wiper > (Rmax-Rmin)/Rstep) begin
    wiper <= (Rmax-Rmin)/Rstep;
  end
end

// Removed the problematic assignment to the wiper signal
// The wiper signal is not supposed to be driven by resistance directly
// assign wiper = resistance[wiper];

endmodule

module top_module(
    input a,
    input b,
    input sel_b1,
    input sel_b2,
    input [15:0] c,
    output [15:0] out
);// 2-to-1 multiplexer
    wire [15:0] mux_out;
    assign mux_out = (sel_b1 == 0) ? a : ((sel_b1 == 1 && sel_b2 == 0) ? b : (a | b));

    // 16-bit adder
    wire [15:0] adder_out;
    assign adder_out = mux_out + c;

    // Functional module
    wire [15:0] func_out;
    assign func_out = (sel_b1 == 0) ? adder_out : (mux_out - c);

    // Final output
    assign out = func_out;

endmodule

